    ctx.charge(p::FormCharge::Expression)?;
    ctx.charge(p::FormCharge::Expression)?;
    ctx.local(0, 0)?;
    ctx.call(0, 0, 1)?;
    ctx.charge(p::FormCharge::Expression)?;
    ctx.literal(2, 1)?;
    ctx.call(1, 0, 2)?;
