fn py_json_quote_heap(heap: &mut dyn p::TemplateHeap, args: &[Value], natives: &[lash_kernel_doc::PreparedNative]) -> Option<Value> {
    let _ = (&heap, natives);
    match args {
        [Value::Text(_) | Value::LongText(_), Value::Bool(_)] => {
            let charge_mark = heap.mark();
            if let Some(value) = (|| {
                let v0 = heap.call(0, &[args[0]])?; let _ = v0;
                heap.bind(v0, None)?;
                let v1 = (natives[0].entry)(&[args[1]])?; let _ = v1;
                if !matches!(v1, Value::Bool(true)) { return None; }
                Some(v0)
            })() { return Some(value); }
            heap.rewind(charge_mark);
            None
        },
        _ => None,
    }
}

